-- GUIMMIA V76.9 - hard guards, audit and operational read models
create or replace function public.guimmia_v769_routed_case_guard() returns trigger language plpgsql as $$ declare routed boolean;begin select exists(select 1 from public.guimmia_case_transaction_profiles p where p.case_id=new.case_id and p.operation_type in('SALE','RENT_LONG_TERM','RENT_TRANSITORY','RENT_STUDENT','RENT_TOURIST_SHORT') and p.route_status='ROUTED') into routed;if not routed then raise exception 'v769_routed_supported_case_required';end if;return new;end $$;
do $$ declare t text;begin foreach t in array array['guimmia_case_internal_assignments','guimmia_contact_channel_profiles','guimmia_consent_records','guimmia_communication_threads','guimmia_communication_events','guimmia_message_outbox','guimmia_appointments','guimmia_appointment_events','guimmia_professional_service_requests','guimmia_professional_service_events','guimmia_agency_operational_tasks','guimmia_agency_task_events','guimmia_agency_escalation_events','guimmia_integration_delivery_events','guimmia_customer_journey_profiles','guimmia_customer_visible_milestones','guimmia_customer_action_requests','guimmia_document_workspaces'] loop execute format('drop trigger if exists %I on public.%I','trg_'||t||'_routed_case',t);execute format('create trigger %I before insert or update on public.%I for each row execute function public.guimmia_v769_routed_case_guard()','trg_'||t||'_routed_case',t);end loop;end $$;
create or replace function public.guimmia_v769_single_agency_guard() returns trigger language plpgsql as $$ begin if tg_op='DELETE' then raise exception 'v769_guimmia_operating_profile_cannot_be_deleted';end if;if new.singleton_key<>'GUIMMIA' or new.code<>'GUIMMIA' then raise exception 'v769_only_guimmia_operating_agency_allowed';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_single_agency_guard on public.guimmia_online_agency_profile;create trigger trg_guimmia_v769_single_agency_guard before update or delete on public.guimmia_online_agency_profile for each row execute function public.guimmia_v769_single_agency_guard();
create or replace function public.guimmia_v769_agency_member_guard() returns trigger language plpgsql as $$ begin if new.status='ACTIVE' and (not new.human_verified or new.user_id is null or new.verified_by is null or new.verified_at is null or new.role_code is null) then raise exception 'v769_active_member_human_verification_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_agency_member_guard on public.guimmia_internal_staff_members;create trigger trg_guimmia_v769_agency_member_guard before insert or update on public.guimmia_internal_staff_members for each row execute function public.guimmia_v769_agency_member_guard();
create or replace function public.guimmia_v769_assignment_guard() returns trigger language plpgsql as $$ declare member_ready boolean;begin select exists(select 1 from public.guimmia_internal_staff_members m where m.id=new.primary_staff_id and m.operating_agency_id=new.operating_agency_id and m.status='ACTIVE' and m.human_verified) into member_ready;if not member_ready or new.assignment_actor_type is distinct from 'HUMAN' or new.assigned_by is null or new.fixed_customer_terms='{}'::jsonb or new.commercial_terms_approved_by is null or new.commercial_terms_approved_at is null then raise exception 'v769_human_case_assignment_and_fixed_terms_required';end if;if new.customer_service_model not in('COMPLETA','MENSILE') then raise exception 'v769_customer_service_model_not_allowed';end if;if new.status='ACCEPTED' and new.handoff_fingerprint is null then raise exception 'v769_assignment_handoff_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_assignment_guard on public.guimmia_case_internal_assignments;create trigger trg_guimmia_v769_assignment_guard before insert or update on public.guimmia_case_internal_assignments for each row execute function public.guimmia_v769_assignment_guard();
create or replace function public.guimmia_v769_contact_guard() returns trigger language plpgsql as $$ begin if new.verified and (new.verified_by is null or new.verified_at is null or new.address_fingerprint is null or new.retention_until is null) then raise exception 'v769_verified_contact_evidence_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_contact_guard on public.guimmia_contact_channel_profiles;create trigger trg_guimmia_v769_contact_guard before insert or update on public.guimmia_contact_channel_profiles for each row execute function public.guimmia_v769_contact_guard();
create or replace function public.guimmia_v769_consent_guard() returns trigger language plpgsql as $$ begin if new.status='GRANTED' and (coalesce(new.actor_type,'') not in('CUSTOMER','HUMAN') or new.actor_id is null or new.legal_basis is null or new.evidence='[]'::jsonb or new.captured_at is null) then raise exception 'v769_consent_evidence_required';end if;if new.status='REVOKED' and new.revoked_at is null then raise exception 'v769_consent_revocation_timestamp_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_consent_guard on public.guimmia_consent_records;create trigger trg_guimmia_v769_consent_guard before insert or update on public.guimmia_consent_records for each row execute function public.guimmia_v769_consent_guard();
create or replace function public.guimmia_v769_communication_guard() returns trigger language plpgsql as $$ begin if new.actor_type in('HUMAN','AI','CUSTOMER','EXTERNAL_PROVIDER') and new.actor_id is null then raise exception 'v769_communication_actor_id_required';end if;if new.material and (new.actor_type<>'HUMAN' or new.actor_id is null or new.decision_rationale is null) then raise exception 'v769_material_communication_human_review_required';end if;if new.event_type in('LEGAL_CONCLUSION','COUNTEROFFER','PRICE_DECISION','CANDIDATE_DECISION') and new.actor_type not in('HUMAN','EXTERNAL_PROVIDER') then raise exception 'v769_ai_material_decision_forbidden';end if;if new.content_hash is null or new.idempotency_key is null then raise exception 'v769_communication_hash_idempotency_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_communication_guard on public.guimmia_communication_events;create trigger trg_guimmia_v769_communication_guard before insert on public.guimmia_communication_events for each row execute function public.guimmia_v769_communication_guard();
create or replace function public.guimmia_v769_message_template_guard() returns trigger language plpgsql as $$ begin if upper(new.category) in('LEGAL','FISCAL','NEGOTIATION','CONTRACT') and (not new.requires_human_approval or new.approved_by is null or new.approved_at is null) then raise exception 'v769_sensitive_template_human_approval_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_message_template_guard on public.guimmia_message_templates;create trigger trg_guimmia_v769_message_template_guard before insert or update on public.guimmia_message_templates for each row execute function public.guimmia_v769_message_template_guard();
create or replace function public.guimmia_v769_outbox_guard() returns trigger language plpgsql as $$ declare consent_ready boolean;begin if new.status in('APPROVED','SENDING','SENT') then select exists(select 1 from public.guimmia_consent_records c where c.id=new.consent_record_id and c.case_id=new.case_id and c.status='GRANTED' and (c.expires_at is null or c.expires_at>now()) and not exists(select 1 from public.guimmia_consent_records r where r.case_id=c.case_id and r.contact_id=c.contact_id and r.purpose=c.purpose and r.channel=c.channel and r.status='REVOKED' and r.created_at>c.created_at)) into consent_ready;if not consent_ready then raise exception 'v769_current_consent_required';end if;if new.material and (new.approval_actor_type is distinct from 'HUMAN' or new.approved_by is null or new.approved_at is null) then raise exception 'v769_material_outbox_human_approval_required';end if;end if;if new.status='SENT' and new.sent_at is null then raise exception 'v769_sent_timestamp_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_outbox_guard on public.guimmia_message_outbox;create trigger trg_guimmia_v769_outbox_guard before insert or update on public.guimmia_message_outbox for each row execute function public.guimmia_v769_outbox_guard();
create or replace function public.guimmia_v769_professional_guard() returns trigger language plpgsql as $$ begin if new.credential_status='VERIFIED' and (new.credential_reference is null or new.credential_valid_until is null or new.credential_valid_until<current_date or new.verified_by is null or new.verified_at is null or new.jurisdiction is null) then raise exception 'v769_current_professional_credentials_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_professional_guard on public.guimmia_professional_profiles;create trigger trg_guimmia_v769_professional_guard before insert or update on public.guimmia_professional_profiles for each row execute function public.guimmia_v769_professional_guard();
create or replace function public.guimmia_v769_appointment_guard() returns trigger language plpgsql as $$ declare conflict_exists boolean;provider_ready boolean;professional_required boolean;begin if new.status='BOOKED' then if new.customer_confirmation_evidence='{}'::jsonb or coalesce(new.booking_actor_type,'') not in('HUMAN','SYSTEM') or new.booked_at is null or (new.booking_actor_type='HUMAN' and new.booked_by is null) then raise exception 'v769_customer_confirmed_booking_required';end if;select exists(select 1 from public.guimmia_appointments a where a.calendar_id=new.calendar_id and a.id<>new.id and a.status='BOOKED' and a.starts_at<new.ends_at and a.ends_at>new.starts_at) into conflict_exists;if conflict_exists then raise exception 'v769_appointment_slot_conflict';end if;select t.professional_required into professional_required from public.guimmia_appointment_types t where t.id=new.appointment_type_id;if professional_required then select exists(select 1 from public.guimmia_professional_profiles p where p.id=new.professional_id and p.credential_status='VERIFIED' and p.active and p.credential_valid_until>=current_date) into provider_ready;if not provider_ready or new.provider_accepted_at is null then raise exception 'v769_verified_provider_acceptance_required';end if;end if;end if;if new.status='COMPLETED' and (new.completed_by is null or new.completed_at is null) then raise exception 'v769_appointment_human_completion_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_appointment_guard on public.guimmia_appointments;create trigger trg_guimmia_v769_appointment_guard before insert or update on public.guimmia_appointments for each row execute function public.guimmia_v769_appointment_guard();
create or replace function public.guimmia_v769_appointment_event_guard() returns trigger language plpgsql as $$ begin if new.event_type='CUSTOMER_CONFIRMED' and (new.actor_type<>'CUSTOMER' or new.actor_id is null or new.payload='{}'::jsonb) then raise exception 'v769_customer_confirmation_event_required';end if;if new.event_type='BOOKED' and (new.actor_type not in('HUMAN','SYSTEM') or (new.actor_type='HUMAN' and new.actor_id is null)) then raise exception 'v769_ai_booking_event_forbidden';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_appointment_event_guard on public.guimmia_appointment_events;create trigger trg_guimmia_v769_appointment_event_guard before insert on public.guimmia_appointment_events for each row execute function public.guimmia_v769_appointment_event_guard();
create or replace function public.guimmia_v769_service_request_guard() returns trigger language plpgsql as $$ declare provider_ready boolean;begin if new.status in('ASSIGNED','ACCEPTED','IN_PROGRESS','DELIVERED','VERIFIED','CLOSED') then select exists(select 1 from public.guimmia_professional_profiles p where p.id=new.professional_id and p.operating_agency_id=new.operating_agency_id and p.credential_status='VERIFIED' and p.active and p.credential_valid_until>=current_date) into provider_ready;if not provider_ready or new.selection_actor_type is distinct from 'HUMAN' or new.selected_by is null or new.selected_at is null or new.scope='{}'::jsonb or new.input_fingerprint is null or new.conflict_check='{}'::jsonb then raise exception 'v769_human_selected_verified_professional_required';end if;end if;if new.status in('DELIVERED','VERIFIED','CLOSED') and (new.deliverable='{}'::jsonb or new.deliverable_fingerprint is null) then raise exception 'v769_professional_deliverable_evidence_required';end if;if new.status in('VERIFIED','CLOSED') and (new.verified_by is null or new.verified_at is null) then raise exception 'v769_human_deliverable_verification_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_service_request_guard on public.guimmia_professional_service_requests;create trigger trg_guimmia_v769_service_request_guard before insert or update on public.guimmia_professional_service_requests for each row execute function public.guimmia_v769_service_request_guard();
create or replace function public.guimmia_v769_task_guard() returns trigger language plpgsql as $$ begin if new.priority='CRITICAL' and not new.visible then raise exception 'v769_critical_task_cannot_be_hidden';end if;if new.status='COMPLETED' and (new.completion_actor_type is distinct from 'HUMAN' or new.completed_by is null or new.completed_at is null or new.evidence='[]'::jsonb or new.completion_fingerprint is null) then raise exception 'v769_task_human_completion_evidence_required';end if;if tg_op='UPDATE' and old.status='COMPLETED' and new.status='OPEN' and new.reopen_reason is null then raise exception 'v769_task_reopen_reason_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_task_guard on public.guimmia_agency_operational_tasks;create trigger trg_guimmia_v769_task_guard before insert or update on public.guimmia_agency_operational_tasks for each row execute function public.guimmia_v769_task_guard();
create or replace function public.guimmia_v769_escalation_guard() returns trigger language plpgsql as $$ begin if new.status='CLOSED' and (new.actor_type is distinct from 'HUMAN' or new.closed_by is null or new.closed_at is null) then raise exception 'v769_escalation_human_closure_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_escalation_guard on public.guimmia_agency_escalation_events;create trigger trg_guimmia_v769_escalation_guard before insert or update on public.guimmia_agency_escalation_events for each row execute function public.guimmia_v769_escalation_guard();
create or replace function public.guimmia_v769_connection_guard() returns trigger language plpgsql as $$ begin if new.status='ENABLED' and (new.credential_reference is null or new.capability_allowlist='[]'::jsonb or new.payload_allowlist='[]'::jsonb or new.approval_actor_type is distinct from 'HUMAN' or new.approved_by is null or new.approved_at is null or new.last_verified_at is null) then raise exception 'v769_enabled_connection_approval_allowlist_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_connection_guard on public.guimmia_integration_connections;create trigger trg_guimmia_v769_connection_guard before insert or update on public.guimmia_integration_connections for each row execute function public.guimmia_v769_connection_guard();
create or replace function public.guimmia_v769_delivery_guard() returns trigger language plpgsql as $$ declare connection_ready boolean;consent_ready boolean;begin select exists(select 1 from public.guimmia_integration_connections c where c.id=new.connection_id and c.status='ENABLED' and c.capability_allowlist ? new.operation_code and c.approval_actor_type='HUMAN') into connection_ready;if not connection_ready then raise exception 'v769_integration_capability_not_allowed';end if;if new.status in('APPROVED','SENDING','DELIVERED') then select exists(select 1 from public.guimmia_consent_records c where c.id=new.customer_consent_id and c.case_id=new.case_id and c.status='GRANTED' and (c.expires_at is null or c.expires_at>now())) into consent_ready;if not consent_ready or new.approval_actor_type is distinct from 'HUMAN' or new.approved_by is null then raise exception 'v769_integration_consent_human_approval_required';end if;end if;if new.status='DELIVERED' and new.remote_ack is null then raise exception 'v769_remote_ack_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_delivery_guard on public.guimmia_integration_delivery_events;create trigger trg_guimmia_v769_delivery_guard before insert on public.guimmia_integration_delivery_events for each row execute function public.guimmia_v769_delivery_guard();
create or replace function public.guimmia_v769_identity_guard() returns trigger language plpgsql as $$ begin if new.status='VERIFIED' and (new.identity_evidence='[]'::jsonb or new.evidence_fingerprint is null or new.verified_by is null or new.verified_at is null or new.evidence_valid_until is null or new.evidence_valid_until<current_date) then raise exception 'v769_current_human_verified_identity_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_identity_guard on public.guimmia_customer_identity_profiles;create trigger trg_guimmia_v769_identity_guard before insert or update on public.guimmia_customer_identity_profiles for each row execute function public.guimmia_v769_identity_guard();
create or replace function public.guimmia_v769_mandate_guard() returns trigger language plpgsql as $$ begin if new.status='ACTIVE' and (new.scope='{}'::jsonb or new.proof_hash is null or new.approval_actor_type is distinct from 'HUMAN' or new.approved_by is null or new.approved_at is null or new.starts_at is null or new.starts_at>now() or (new.ends_at is not null and new.ends_at<=now())) then raise exception 'v769_active_mandate_scope_human_approval_required';end if;if new.status='REVOKED' and new.revoked_at is null then raise exception 'v769_mandate_revocation_timestamp_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_mandate_guard on public.guimmia_customer_mandates;create trigger trg_guimmia_v769_mandate_guard before insert or update on public.guimmia_customer_mandates for each row execute function public.guimmia_v769_mandate_guard();
create or replace function public.guimmia_v769_privacy_request_guard() returns trigger language plpgsql as $$ begin if new.due_at<=new.received_at then raise exception 'v769_privacy_due_date_invalid';end if;if new.status='FULFILLED' and (not new.identity_verified or not new.export_redacted or new.completed_by is null or new.completed_at is null) then raise exception 'v769_privacy_fulfillment_human_redacted_export_required';end if;if new.status='REJECTED' and (new.decision_reason is null or new.completed_by is null or new.completed_at is null) then raise exception 'v769_privacy_rejection_human_reason_required';end if;if new.status='CLOSED' and (not new.identity_verified or new.completed_by is null or new.completed_at is null) then raise exception 'v769_privacy_closure_human_identity_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_privacy_request_guard on public.guimmia_privacy_requests;create trigger trg_guimmia_v769_privacy_request_guard before insert or update on public.guimmia_privacy_requests for each row execute function public.guimmia_v769_privacy_request_guard();
create or replace function public.guimmia_v769_slot_hold_guard() returns trigger language plpgsql as $$ declare conflict_exists boolean;appointment_ready boolean;begin if new.created_by_actor_type<>'SYSTEM' and new.created_by is null then raise exception 'v769_slot_hold_actor_required';end if;if new.status='HELD' then if new.held_until<=now() then raise exception 'v769_slot_hold_expired';end if;select exists(select 1 from public.guimmia_appointment_slot_holds h where h.calendar_id=new.calendar_id and h.id<>new.id and h.status='HELD' and h.held_until>now() and h.starts_at<new.ends_at and h.ends_at>new.starts_at) into conflict_exists;if conflict_exists then raise exception 'v769_slot_hold_conflict';end if;end if;if new.status='CONVERTED' then select exists(select 1 from public.guimmia_appointments a where a.id=new.appointment_id and a.case_id=new.case_id and a.calendar_id=new.calendar_id and a.status in('CUSTOMER_CONFIRMED','BOOKED') and a.slot_fingerprint=new.slot_fingerprint) into appointment_ready;if not appointment_ready then raise exception 'v769_slot_hold_customer_confirmation_required';end if;end if;return new;end $$;drop trigger if exists trg_guimmia_v769_slot_hold_guard on public.guimmia_appointment_slot_holds;create trigger trg_guimmia_v769_slot_hold_guard before insert or update on public.guimmia_appointment_slot_holds for each row execute function public.guimmia_v769_slot_hold_guard();
create or replace function public.guimmia_v769_voice_session_guard() returns trigger language plpgsql as $$ declare connection_ready boolean;call_consent_ready boolean;recording_consent_ready boolean;begin if new.status in('ACTIVE','HANDOFF_PENDING','COMPLETED') then select exists(select 1 from public.guimmia_integration_connections c where c.id=new.connection_id and c.operating_agency_id=new.operating_agency_id and c.status='ENABLED' and c.capability_allowlist ? 'VOICE_CALL' and c.approval_actor_type='HUMAN') into connection_ready;select exists(select 1 from public.guimmia_consent_records c where c.id=new.call_consent_id and c.case_id=new.case_id and c.status='GRANTED' and (c.expires_at is null or c.expires_at>now())) into call_consent_ready;if not connection_ready or not call_consent_ready or not new.identity_verified then raise exception 'v769_voice_connection_consent_identity_required';end if;if new.recording_enabled then select exists(select 1 from public.guimmia_consent_records c where c.id=new.recording_consent_id and c.case_id=new.case_id and c.status='GRANTED' and (c.expires_at is null or c.expires_at>now())) into recording_consent_ready;if not recording_consent_ready then raise exception 'v769_recording_consent_required';end if;end if;end if;if new.material_intent_detected and new.handoff_staff_id is null then raise exception 'v769_material_voice_intent_handoff_required';end if;if new.status='COMPLETED' and (new.summary_hash is null or new.summary_approval_actor_type is distinct from 'HUMAN' or new.summary_approved_by is null or new.summary_approved_at is null) then raise exception 'v769_voice_summary_human_approval_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_voice_session_guard on public.guimmia_voice_call_sessions;create trigger trg_guimmia_v769_voice_session_guard before insert or update on public.guimmia_voice_call_sessions for each row execute function public.guimmia_v769_voice_session_guard();
create or replace function public.guimmia_v769_voice_event_guard() returns trigger language plpgsql as $$ declare previous_hash text;begin if new.event_type in('TRANSCRIPT','INTENT','APPOINTMENT_PROPOSED','APPOINTMENT_CONFIRMED') and new.transcript_hash is null then raise exception 'v769_voice_transcript_hash_required';end if;if new.event_type='APPOINTMENT_CONFIRMED' and (new.actor_type<>'CUSTOMER' or new.actor_id is null or new.payload='{}'::jsonb) then raise exception 'v769_voice_customer_confirmation_evidence_required';end if;select event_hash into previous_hash from public.guimmia_voice_call_events where session_id=new.session_id order by id desc limit 1;if previous_hash is distinct from new.previous_event_hash then raise exception 'v769_voice_audit_chain_broken';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_voice_event_guard on public.guimmia_voice_call_events;create trigger trg_guimmia_v769_voice_event_guard before insert on public.guimmia_voice_call_events for each row execute function public.guimmia_v769_voice_event_guard();
create or replace function public.guimmia_v769_webhook_guard() returns trigger language plpgsql as $$ begin if new.status in('VERIFIED','PROCESSED') and (not new.signature_valid or new.signature_timestamp is null or abs(extract(epoch from(now()-new.signature_timestamp)))>300) then raise exception 'v769_current_webhook_signature_required';end if;if new.status='PROCESSED' and new.processed_at is null then raise exception 'v769_webhook_processed_timestamp_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_webhook_guard on public.guimmia_integration_webhook_inbox;create trigger trg_guimmia_v769_webhook_guard before insert or update on public.guimmia_integration_webhook_inbox for each row execute function public.guimmia_v769_webhook_guard();
create or replace function public.guimmia_v769_recovery_guard() returns trigger language plpgsql as $$ begin if new.attempt>new.max_attempts and new.status not in('ESCALATED','COMPENSATING') then raise exception 'v769_retry_exhausted_human_recovery_required';end if;if new.status='COMPENSATING' and (new.compensation='{}'::jsonb or new.approval_actor_type is distinct from 'HUMAN' or new.approved_by is null or new.approved_at is null) then raise exception 'v769_compensation_human_approval_required';end if;if new.status='RESOLVED' and new.resolution_fingerprint is null then raise exception 'v769_recovery_resolution_fingerprint_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_recovery_guard on public.guimmia_recovery_cases;create trigger trg_guimmia_v769_recovery_guard before insert or update on public.guimmia_recovery_cases for each row execute function public.guimmia_v769_recovery_guard();
create or replace function public.guimmia_v769_customer_journey_guard() returns trigger language plpgsql as $$ declare guimmia_profile boolean;owner_ready boolean;begin select exists(select 1 from public.guimmia_online_agency_profile a where a.id=new.operating_agency_id and a.code='GUIMMIA' and a.singleton_key='GUIMMIA') into guimmia_profile;if not guimmia_profile then raise exception 'v769_customer_journey_must_belong_to_guimmia';end if;if new.status in('SERVICE_SELECTED','ACTIVE','WAITING_CUSTOMER','WAITING_PROFESSIONAL','COMPLETED') and (new.customer_service_model not in('COMPLETA','MENSILE') or not new.service_scope_acknowledged or not new.fixed_compensation_disclosed) then raise exception 'v769_customer_service_scope_and_fixed_compensation_required';end if;if new.status in('ACTIVE','WAITING_CUSTOMER','WAITING_PROFESSIONAL','COMPLETED') then select exists(select 1 from public.guimmia_internal_staff_members m where m.id=new.internal_owner_id and m.operating_agency_id=new.operating_agency_id and m.status='ACTIVE' and m.human_verified) into owner_ready;if not owner_ready or new.last_context_hash is null then raise exception 'v769_internal_owner_and_customer_context_required';end if;end if;if new.status='COMPLETED' and new.completed_at is null then raise exception 'v769_customer_journey_completion_timestamp_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_customer_journey_guard on public.guimmia_customer_journey_profiles;create trigger trg_guimmia_v769_customer_journey_guard before insert or update on public.guimmia_customer_journey_profiles for each row execute function public.guimmia_v769_customer_journey_guard();
create or replace function public.guimmia_v769_customer_milestone_guard() returns trigger language plpgsql as $$ begin if new.visible and (new.title is null or new.customer_message is null or (new.status not in('COMPLETED','CANCELLED') and new.next_action is null)) then raise exception 'v769_customer_visible_milestone_explanation_required';end if;if new.status='COMPLETED' and (new.evidence='[]'::jsonb or (new.material and (new.human_approved_by is null or new.human_approved_at is null))) then raise exception 'v769_milestone_completion_evidence_and_human_approval_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_customer_milestone_guard on public.guimmia_customer_visible_milestones;create trigger trg_guimmia_v769_customer_milestone_guard before insert or update on public.guimmia_customer_visible_milestones for each row execute function public.guimmia_v769_customer_milestone_guard();
create or replace function public.guimmia_v769_customer_action_guard() returns trigger language plpgsql as $$ begin if new.requested_by_actor_type in('HUMAN','AI') and new.requested_by is null then raise exception 'v769_customer_action_requester_required';end if;if new.status='COMPLETED' and (new.completed_by_actor_type is null or new.completed_by is null or new.completed_at is null or new.customer_response='{}'::jsonb) then raise exception 'v769_customer_action_completion_evidence_required';end if;if new.status='COMPLETED' and new.action_type in('APPROVE_LISTING','CONFIRM_APPOINTMENT','APPROVE_DOCUMENT','ACCEPT_OFFER','COUNTEROFFER','CANDIDATE_SELECTION') and new.completed_by_actor_type<>'CUSTOMER' then raise exception 'v769_material_customer_action_cannot_be_completed_by_ai_or_system';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_customer_action_guard on public.guimmia_customer_action_requests;create trigger trg_guimmia_v769_customer_action_guard before insert or update on public.guimmia_customer_action_requests for each row execute function public.guimmia_v769_customer_action_guard();
create or replace function public.guimmia_v769_document_workspace_guard() returns trigger language plpgsql as $$ begin if new.status in('PREPARED','HUMAN_REVIEW','CUSTOMER_REVIEW','APPROVED','SIGNED','ARCHIVED') and (new.inputs='{}'::jsonb or new.template_version is null or new.content_hash is null or new.dynamic_rulesets='[]'::jsonb) then raise exception 'v769_document_inputs_version_hash_rulesets_required';end if;if new.professional_review_required and new.status in('CUSTOMER_REVIEW','APPROVED','SIGNED','ARCHIVED') and (new.professional_reviewed_by is null or new.professional_reviewed_at is null) then raise exception 'v769_required_professional_document_review_missing';end if;if new.status in('CUSTOMER_REVIEW','APPROVED','SIGNED','ARCHIVED') and (new.human_approved_by is null or new.human_approved_at is null) then raise exception 'v769_document_human_approval_required';end if;if new.status in('APPROVED','SIGNED','ARCHIVED') and new.customer_review_evidence='{}'::jsonb then raise exception 'v769_document_customer_review_evidence_required';end if;if new.status in('SIGNED','ARCHIVED') and (new.signature_evidence='{}'::jsonb or new.signed_at is null) then raise exception 'v769_document_signature_evidence_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v769_document_workspace_guard on public.guimmia_document_workspaces;create trigger trg_guimmia_v769_document_workspace_guard before insert or update on public.guimmia_document_workspaces for each row execute function public.guimmia_v769_document_workspace_guard();
create or replace function public.guimmia_v769_event_immutable() returns trigger language plpgsql as $$ begin raise exception 'V76.9 operational events are immutable; append a compensating event';end $$;do $$ declare t text;begin foreach t in array array['guimmia_communication_events','guimmia_appointment_events','guimmia_professional_service_events','guimmia_agency_task_events','guimmia_integration_delivery_events','guimmia_voice_call_events'] loop execute format('drop trigger if exists %I on public.%I','trg_'||t||'_immutable',t);execute format('create trigger %I before update or delete on public.%I for each row execute function public.guimmia_v769_event_immutable()','trg_'||t||'_immutable',t);end loop;end $$;
create or replace function public.guimmia_v769_invalidate_on_route_change() returns trigger language plpgsql as $$ begin if old.operation_type is distinct from new.operation_type or new.route_status is distinct from 'ROUTED' then update public.guimmia_case_internal_assignments set status='TRANSFER_PENDING',updated_at=now() where case_id=new.case_id and status in('ASSIGNED','ACCEPTED');update public.guimmia_message_outbox set status='CANCELLED',updated_at=now() where case_id=new.case_id and status in('PENDING','APPROVED','SENDING');update public.guimmia_appointments set status='CANCELLED',updated_at=now() where case_id=new.case_id and status in('DRAFT','PROPOSED','CUSTOMER_CONFIRMED','BOOKED','RESCHEDULE_PENDING');update public.guimmia_appointment_slot_holds set status='RELEASED',updated_at=now() where case_id=new.case_id and status='HELD';update public.guimmia_voice_call_sessions set status='ABORTED',updated_at=now() where case_id=new.case_id and status in('CREATED','CONSENT_PENDING','ACTIVE','HANDOFF_PENDING');update public.guimmia_professional_service_requests set status='CANCELLED',updated_at=now() where case_id=new.case_id and status in('DRAFT','SUBMITTED','ASSIGNED');update public.guimmia_agency_operational_tasks set status='BLOCKED',updated_at=now() where case_id=new.case_id and status in('OPEN','IN_PROGRESS');update public.guimmia_recovery_cases set status='ESCALATED',updated_at=now() where case_id=new.case_id and status not in('RESOLVED','ESCALATED');end if;return new;end $$;drop trigger if exists trg_guimmia_v769_route_change on public.guimmia_case_transaction_profiles;create trigger trg_guimmia_v769_route_change before update of operation_type,route_status on public.guimmia_case_transaction_profiles for each row execute function public.guimmia_v769_invalidate_on_route_change();
create or replace function public.guimmia_agency_case_summary(p_case_id uuid) returns table(case_id uuid,operation_type text,operating_agency_id uuid,assignment_status text,open_tasks bigint,next_appointment timestamptz,open_services bigint,open_escalations bigint) language sql stable security definer set search_path=public as $$ select c.id,p.operation_type,a.operating_agency_id,coalesce(a.status,'UNASSIGNED'),(select count(*) from public.guimmia_agency_operational_tasks t where t.case_id=c.id and t.status not in('COMPLETED','CANCELLED')),(select min(x.starts_at) from public.guimmia_appointments x where x.case_id=c.id and x.status='BOOKED' and x.starts_at>=now()),(select count(*) from public.guimmia_professional_service_requests s where s.case_id=c.id and s.status not in('CLOSED','CANCELLED')),(select count(*) from public.guimmia_agency_escalation_events e where e.case_id=c.id and e.status<>'CLOSED') from public.guimmia_brain_cases c join public.guimmia_case_transaction_profiles p on p.case_id=c.id left join public.guimmia_case_internal_assignments a on a.case_id=c.id where c.id=p_case_id;$$;revoke all on function public.guimmia_agency_case_summary(uuid) from public;
create or replace function public.guimmia_agency_appointment_queue(p_operating_agency_id uuid default null) returns table(appointment_id uuid,case_id uuid,operating_agency_id uuid,status text,starts_at timestamptz,timezone text,professional_id uuid) language sql stable security definer set search_path=public as $$ select a.id,a.case_id,a.operating_agency_id,a.status,a.starts_at,a.timezone,a.professional_id from public.guimmia_appointments a where a.status in('PROPOSED','CUSTOMER_CONFIRMED','BOOKED','RESCHEDULE_PENDING') and (p_operating_agency_id is null or a.operating_agency_id=p_operating_agency_id) order by a.starts_at;$$;revoke all on function public.guimmia_agency_appointment_queue(uuid) from public;
create or replace function public.guimmia_agency_followup_queue(p_operating_agency_id uuid default null) returns table(thread_id uuid,case_id uuid,operating_agency_id uuid,status text,next_followup_at timestamptz,assigned_staff_id uuid) language sql stable security definer set search_path=public as $$ select t.id,t.case_id,t.operating_agency_id,t.status,t.next_followup_at,t.assigned_staff_id from public.guimmia_communication_threads t where t.status not in('RESOLVED','ARCHIVED') and (t.next_followup_at is null or t.next_followup_at<=now()) and (p_operating_agency_id is null or t.operating_agency_id=p_operating_agency_id) order by t.next_followup_at nulls first;$$;revoke all on function public.guimmia_agency_followup_queue(uuid) from public;
create or replace function public.guimmia_agency_sla_dashboard(p_operating_agency_id uuid default null) returns table(metric text,value bigint) language sql stable security definer set search_path=public as $$ select 'OPEN_TASKS',count(*) from public.guimmia_agency_operational_tasks where status not in('COMPLETED','CANCELLED') and (p_operating_agency_id is null or operating_agency_id=p_operating_agency_id) union all select 'OVERDUE_TASKS',count(*) from public.guimmia_agency_operational_tasks where status not in('COMPLETED','CANCELLED') and due_at<now() and (p_operating_agency_id is null or operating_agency_id=p_operating_agency_id) union all select 'OPEN_ESCALATIONS',count(*) from public.guimmia_agency_escalation_events where status<>'CLOSED' and (p_operating_agency_id is null or operating_agency_id=p_operating_agency_id) union all select 'PENDING_APPOINTMENTS',count(*) from public.guimmia_appointments where status in('PROPOSED','CUSTOMER_CONFIRMED','RESCHEDULE_PENDING') and (p_operating_agency_id is null or operating_agency_id=p_operating_agency_id);$$;revoke all on function public.guimmia_agency_sla_dashboard(uuid) from public;
create or replace function public.guimmia_agency_voice_handoff_queue(p_operating_agency_id uuid default null) returns table(session_id uuid,case_id uuid,operating_agency_id uuid,status text,purpose text,material_intent_detected boolean,handoff_staff_id uuid,updated_at timestamptz) language sql stable security definer set search_path=public as $$ select s.id,s.case_id,s.operating_agency_id,s.status,s.purpose,s.material_intent_detected,s.handoff_staff_id,s.updated_at from public.guimmia_voice_call_sessions s where s.status='HANDOFF_PENDING' and (p_operating_agency_id is null or s.operating_agency_id=p_operating_agency_id) order by s.updated_at;$$;revoke all on function public.guimmia_agency_voice_handoff_queue(uuid) from public;
create or replace function public.guimmia_agency_recovery_queue(p_operating_agency_id uuid default null) returns table(recovery_id uuid,case_id uuid,operating_agency_id uuid,source_type text,status text,attempt integer,max_attempts integer,assigned_staff_id uuid,updated_at timestamptz) language sql stable security definer set search_path=public as $$ select r.id,r.case_id,r.operating_agency_id,r.source_type,r.status,r.attempt,r.max_attempts,r.assigned_staff_id,r.updated_at from public.guimmia_recovery_cases r where r.status not in('RESOLVED') and (p_operating_agency_id is null or r.operating_agency_id=p_operating_agency_id) order by case when r.status='ESCALATED' then 0 else 1 end,r.updated_at;$$;revoke all on function public.guimmia_agency_recovery_queue(uuid) from public;
create or replace function public.guimmia_customer_case_progress(p_case_id uuid) returns table(case_id uuid,operating_agency_id uuid,party_role text,customer_intent text,customer_service_model text,journey_status text,completed_milestones bigint,total_milestones bigint,progress_percent integer,next_action text,next_due_at timestamptz) language sql stable security definer set search_path=public as $$ select j.case_id,j.operating_agency_id,j.party_role,j.customer_intent,j.customer_service_model,j.status,(select count(*) from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status='COMPLETED'),(select count(*) from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status<>'CANCELLED'),case when (select count(*) from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status<>'CANCELLED')=0 then 0 else round(100.0*(select count(*) from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status='COMPLETED')/(select count(*) from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status<>'CANCELLED'))::int end,(select m.next_action from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status not in('COMPLETED','CANCELLED') order by m.sequence_no limit 1),(select m.due_at from public.guimmia_customer_visible_milestones m where m.journey_id=j.id and m.visible and m.status not in('COMPLETED','CANCELLED') order by m.sequence_no limit 1) from public.guimmia_customer_journey_profiles j where j.case_id=p_case_id;$$;revoke all on function public.guimmia_customer_case_progress(uuid) from public;
create or replace function public.guimmia_customer_action_center(p_case_id uuid) returns table(action_id uuid,action_type text,status text,due_at timestamptz,payload jsonb,created_at timestamptz) language sql stable security definer set search_path=public as $$ select a.id,a.action_type,a.status,a.due_at,a.payload,a.created_at from public.guimmia_customer_action_requests a where a.case_id=p_case_id and a.status in('OPEN','VIEWED') order by a.due_at nulls last,a.created_at;$$;revoke all on function public.guimmia_customer_action_center(uuid) from public;
